def ukuran_letak_berkelompok(tepi_bawah, panjang_kelas, frekuensi, bagian, ke):
    n = sum(frekuensi)
    letak = (ke * n) / bagian
    jf = 0
    for lb, f in zip(tepi_bawah, frekuensi):
        if jf + f >= letak:
            return float(lb + panjang_kelas * (letak - jf) / f)
        jf += f
    raise ValueError('Letak berada di luar total frekuensi')

