import math
from scipy.stats import norm, t

def sk_rata_rata_1pop(x_bar, std_val, n, alpha, sigma_diketahui=True):
    se = std_val / math.sqrt(n)
    crit = norm.ppf(1.0 - alpha / 2.0) if sigma_diketahui else t.ppf(1.0 - alpha / 2.0, df=n - 1)
    me = float(crit * se)
    return (x_bar - me, x_bar + me)

def sk_proporsi_1pop(sukses, n, alpha):
    p_hat = sukses / n
    se = math.sqrt(p_hat * (1.0 - p_hat) / n)
    crit = float(norm.ppf(1.0 - alpha / 2.0))
    me = crit * se
    return (p_hat - me, p_hat + me)

