def _pval_dari_cdf(cdf_val, arah):
    if arah == 'kanan':
        return 1.0 - cdf_val
    if arah == 'kiri':
        return cdf_val
    return 2.0 * min(cdf_val, 1.0 - cdf_val)

def uji_t_1pop(x_bar, s, n, mu0, alpha=0.05, arah='dua'):
    t_stat = (x_bar - mu0) / (s / math.sqrt(n))
    p_val = float(_pval_dari_cdf(t.cdf(t_stat, df=n - 1), arah))
    return {'stat': float(t_stat), 'p_value': p_val, 'tolak_h0': p_val < alpha}

def uji_proporsi_1pop(sukses, n, p0, alpha=0.05, arah='dua'):
    p_hat = sukses / n
    z_stat = (p_hat - p0) / math.sqrt(p0 * (1.0 - p0) / n)
    p_val = float(_pval_dari_cdf(norm.cdf(z_stat), arah))
    return {'stat': float(z_stat), 'p_value': p_val, 'tolak_h0': p_val < alpha}

