import math

def _median_sorted(arr):
    m = len(arr)
    mid = m // 2
    if m % 2 == 1:
        return float(arr[mid])
    return 0.5 * (arr[mid - 1] + arr[mid])

def _interp_q(arr, i):
    n = len(arr)
    pos = i * (n + 1) / 4.0
    idx = int(math.floor(pos)) - 1
    frac = pos - math.floor(pos)
    if frac == 0:
        return float(arr[idx])
    return float(arr[idx] + frac * (arr[idx + 1] - arr[idx]))

def bandingkan_kuartil(data):
    arr = sorted(data)
    n = len(arr)
    mid = n // 2
    bawah = arr[:mid]
    atas = arr[mid + 1:] if n % 2 == 1 else arr[mid:]
    bq1 = _median_sorted(bawah)
    bq2 = _median_sorted(arr)
    bq3 = _median_sorted(atas)
    iq1 = _interp_q(arr, 1)
    iq2 = _interp_q(arr, 2)
    iq3 = _interp_q(arr, 3)
    return {
        'belah_dua': (bq1, bq2, bq3, bq3 - bq1),
        'interpolasi': (iq1, iq2, iq3, iq3 - iq1),
    }

