import math

def analisis_distribusi_bersama(x_vals, y_vals, p_matrix):
    total = sum(sum(row) for row in p_matrix)
    if not math.isclose(total, 1.0, abs_tol=1e-6):
        raise ValueError('Jumlah peluang bersama harus 1')
    gx = [sum(row) for row in p_matrix]
    hy = [sum(p_matrix[i][j] for i in range(len(x_vals))) for j in range(len(y_vals))]
    indep = all(
        math.isclose(p_matrix[i][j], gx[i] * hy[j], abs_tol=1e-6)
        for i in range(len(x_vals))
        for j in range(len(y_vals))
    )
    ex = sum(x * g for x, g in zip(x_vals, gx))
    ey = sum(y * h for y, h in zip(y_vals, hy))
    exy = sum(
        x_vals[i] * y_vals[j] * p_matrix[i][j]
        for i in range(len(x_vals))
        for j in range(len(y_vals))
    )
    return {
        'marginal_x': [float(v) for v in gx],
        'marginal_y': [float(v) for v in hy],
        'independen': indep,
        'cov': float(exy - ex * ey),
    }

