import math

def geometrik_ut(p, k_max):
    q = 1.0 - p
    pmf_k = p * (q ** (k_max - 1))
    cdf_k = 1.0 - (q ** k_max)
    return {
        'pmf_k': float(pmf_k),
        'cdf_k': float(cdf_k),
        'mean': float(1.0 / p),
        'var': float(q / (p ** 2)),
    }

def binom_negatif_ut(p, c, n_total):
    q = 1.0 - p
    pmf_n = math.comb(n_total - 1, c - 1) * (p ** c) * (q ** (n_total - c))
    return {
        'pmf_n': float(pmf_n),
        'mean': float(c / p),
        'var': float(c * q / (p ** 2)),
    }

