import math
from scipy.stats import norm

def clt_mean_fpc(mu, sigma, n, N, batas_x):
    pakai_fpc = (N is not None) and ((n / N) > 0.05)
    se = sigma / math.sqrt(n)
    if pakai_fpc:
        se *= math.sqrt((N - n) / (N - 1))
    z = (batas_x - mu) / se
    return {
        'pakai_fpc': pakai_fpc,
        'se': float(se),
        'z': float(z),
        'peluang': float(norm.sf(z)),
    }

def clt_proporsi(p_pop, n, p_batas):
    se = math.sqrt(p_pop * (1.0 - p_pop) / n)
    return float(norm.sf(p_batas, loc=p_pop, scale=se))

